class Solution {
public:
    string decodeMessage(string key, string message) {
        char map[26] = {};
        char current = 'a';
        for (char c : key) {
            if (c != ' ' && map[c - 'a'] == 0) {
                map[c - 'a'] = current++;
            }
        }
        string result;
        for (char c : message) {
            if (c == ' ') {
                result += ' ';
            } else {
                result += map[c - 'a'];
            }
        }
        return result;
    }
};
